import json
from pathlib import Path
q=Path('content/grammar.json');d=json.loads(q.read_text(encoding='utf8'))
P={'一方で':('on the other hand; while','V/adj plain + 一方で',[('便利な一方で、値段が高い。','べんりないっぽうで、ねだんがたかい。','Benri na ippō de nedan ga takai.','While convenient, it is expensive.'),('兄は外で働く一方で、妹は家で勉強する。','あにはそとではたらくいっぽうで、いもうとはいえでべんきょうする。','Ani wa soto de hataraku ippō de imōto wa ie de benkyō suru.','While my brother works outside, my sister studies at home.'),('収入が増える一方で支出も増えた。','しゅうにゅうがふえるいっぽうでししゅつもふえた。','Shūnyū ga fueru ippō de shishutsu mo fueta.','While income rose, expenses also rose.')],'便利な（　）、値段が高い。'), '反面':('on the other hand; downside','V/adj plain + 反面',[('自由な反面、責任も重い。','じゆうなはんめん、せきにんもおもい。','Jiyū na hanmen sekinin mo omoi.','While it is free, the responsibility is heavy.'),('都会は便利な反面、家賃が高い。','とかいはべんりなはんめん、やちんがたかい。','Tokai wa benri na hanmen yachin ga takai.','Cities are convenient, but rent is high.'),('簡単な反面、飽きやすい。','かんたんなはんめん、あきやすい。','Kantan na hanmen aki yasui.','While simple, it is easy to get bored with.')],'都会は便利な（　）、家賃が高い。'), 'はずだ':('should; be expected to','V/adj plain + はずだ',[('彼はもう到着したはずだ。','かれはもうとうちゃくしたはずだ。','Kare wa mō tōchaku shita hazu da.','He should have arrived already.'),('この店は月曜も開いているはずです。','このみせはげつようもあいているはずです。','Kono mise wa getsuyō mo aite iru hazu desu.','This shop should be open Mondays too.'),('鍵は机の上にあるはずだ。','かぎはつくえのうえにあるはずだ。','Kagi wa tsukue no ue ni aru hazu da.','The key should be on the desk.')],'彼はもう着いた（　）だ。'), 'はずがない':('cannot possibly','V/adj plain + はずがない',[('彼がそんなうそをつくはずがない。','かれがそんなうそをつくはずがない。','Kare ga sonna uso o tsuku hazu ga nai.','He cannot possibly tell such a lie.'),('この箱に入るはずがない。','このはこにはいるはずがない。','Kono hako ni hairu hazu ga nai.','It cannot possibly fit in this box.'),('一日で全部覚えられるはずがない。','いちにちでぜんぶおぼえられるはずがない。','Ichinichi de zenbu oboerareru hazu ga nai.','I cannot possibly memorize it all in one day.')],'彼がうそをつく（　）。'), 'わけだ':('that explains why; naturally','V/adj plain + わけだ',[('毎日練習した。上手になるわけだ。','まいにちれんしゅうした。じょうずになるわけだ。','Mainichi renshū shita. Jōzu ni naru wake da.','You practiced daily; no wonder you improved.'),('道が混んでいた。遅れたわけだ。','みちがこんでいた。おくれたわけだ。','Michi ga konde ita. Okureta wake da.','The road was crowded; that explains the delay.'),('彼は医者だから詳しいわけだ。','かれはいしゃだからくわしいわけだ。','Kare wa isha da kara kuwashii wake da.','He is a doctor, so naturally he knows the details.')],'練習したから上手になった（　）だ。'), 'わけではない':('it does not mean that; not necessarily','V/adj plain + わけではない',[('嫌いなわけではない。','きらいなわけではない。','Kirai na wake de wa nai.','It is not that I dislike it.'),('全部分かったわけではない。','ぜんぶわかったわけではない。','Zenbu wakatta wake de wa nai.','It does not mean I understood everything.'),('いつも忙しいわけではありません。','いつもいそがしいわけではありません。','Itsumo isogashii wake de wa arimasen.','It is not that I am always busy.')],'全部分かった（　）。')}
for pat,(m,form,ex,prompt) in P.items():
 i=next(i for l in d['lessons'] for i in l['items'] if i['pattern']==pat);i.update(meaning=m,formation=form,usage='Use the pattern for the logical relationship shown.',register='neutral',nuance='The surrounding context determines the strength of the inference or contrast.',examples=[{'jp':a,'reading':b,'romaji':c,'en':e} for a,b,c,e in ex],mistake='Do not confuse expectation with certainty or contrast with cause.',comparison='Compare the evidential strength and polarity of neighboring forms.',question={'prompt':prompt,'options':[pat,'ために','以来','ばかり'],'answer':pat,'explanation':'The context calls for this pattern.'})
q.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8');print('patched',len(P))
